def parse_weight(text: str) -> int:
    """Parse a package weight like '1.5 kg' into whole grams.

    Accepts an integer or decimal number (with '.' separator), optional
    whitespace, and one of the units g, kg, lb, or oz (case-insensitive).
    Raises ValueError for missing/unknown unit, malformed numbers, negative
    values, or ',' as the decimal separator.
    """
    if not isinstance(text, str):
        raise ValueError(f"Expected str, got {type(text).__name__}")

    s = text.strip()
    if not s:
        raise ValueError("Missing weight")

    # Split off the trailing unit token.
    match = __import__("re").match(r"^(\S+)\s*([A-Za-z]+)$", s)
    if not match:
        # No unit token found (e.g., just a number).
        raise ValueError("Missing or unknown unit")

    num_str, unit_str = match.group(1), match.group(2)

    # Validate the number part.
    if num_str.startswith("-"):
        raise ValueError("Negative values are not allowed")

    if "," in num_str:
        raise ValueError("',' is not a valid decimal separator")

    # Allow at most one '.' and no leading/trailing '.'
    if num_str.count(".") > 1:
        raise ValueError("Invalid number")
    if num_str.startswith(".") or num_str.endswith("."):
        raise ValueError("Invalid number")

    # Reject any character that isn't a digit or '.'
    for ch in num_str:
        if ch != "." and not ch.isdigit():
            raise ValueError("Invalid number")

    try:
        value = float(num_str)
    except ValueError:
        raise ValueError("Invalid number")

    if value < 0:
        raise ValueError("Negative values are not allowed")

    unit = unit_str.lower()
    if unit == "g":
        grams = value
    elif unit == "kg":
        grams = value * 1000
    elif unit == "lb":
        grams = value * 453.59237
    elif unit == "oz":
        grams = value * 28.349523125
    else:
        raise ValueError(f"Unknown unit: {unit_str}")

    return int(round(grams))
